package com.yuegang.zhihui.notification.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.notification.application.NotificationQueryService;import com.yuegang.zhihui.notification.security.NotificationSecurity;import jakarta.servlet.http.HttpServletRequest;import java.util.Map;import org.springframework.web.bind.annotation.*;@RestController public final class NotificationQueryController{private final NotificationQueryService service;private final NotificationSecurity security;public NotificationQueryController(NotificationQueryService s,NotificationSecurity x){service=s;security=x;}@GetMapping("/api/v1/notifications/unread-count")ApiResponse<Map<String,Long>>unread(HttpServletRequest r){return ApiResponse.success(Map.of("count",service.unread(security.user(r))),TraceIdResolver.resolve(r));}@PutMapping("/api/v1/notifications/read-all")ApiResponse<Map<String,Integer>>readAll(HttpServletRequest r){return ApiResponse.success(Map.of("updated",service.readAll(security.user(r))),TraceIdResolver.resolve(r));}}
